package com.tecsup.model; import jakarta.persistence.*; @Entity public class Pedido { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long clienteId,productoId; private Integer cantidad; private String estado="PENDIENTE"; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getClienteId(){return clienteId;} public void setClienteId(Long v){clienteId=v;} public Long getProductoId(){return productoId;} public void setProductoId(Long v){productoId=v;} public Integer getCantidad(){return cantidad;} public void setCantidad(Integer v){cantidad=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }
